; vline.asm -- chapter 22: a line down the screen with down
; generated by gen22.py
        INCLUDE "msx.inc"
        OUTPUT "vline.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; A line down the screen at x = 100: vaddr finds the byte of its top pixel,
; and down the byte below, 191 times.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the picture is drawn
        VDP_REG 0, $02          ; Graphic II: 256 x 192 pixels (chapter 22)
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000, 6,144 bytes
        VDP_REG 4, $03          ; patterns           $0000, 6,144 bytes
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: every pixel paper
        ld bc, 6144
g2p:    xor a
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2p
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld bc, 6144
g2c:    ld a, $1F
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, g2c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
g2n:    xor a
g2n1:   out (VDP_DATA), a
        inc a
        jr nz, g2n1
        djnz g2n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld b, 100               ; x
        ld c, 0                 ; y
        call vaddr              ; HL: the byte of (100, 0)
        ld d, 192
vl:     ld a, l                 ; the write address
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        ld a, $08               ; pixel 100: bit 3 of its byte
        out (VDP_DATA), a
d0:     call down
d1:     dec d
        jr nz, vl
        VDP_REG 1, $C0          ; the display on
done:   jr done

; down: HL = the address of a byte -> HL = the byte one line below it, in
; the patterns of a Graphic II screen whose names run 0 to 255 in each third.
; Uses A.
down:   inc l                   ;  5: one line down, inside the cell
        ld a, l                 ;  5
        and 7                   ;  8
        ret nz                  ; 12, 6 if not taken
        ld a, l                 ;  5: it was the cell's last line, and L
        sub 8                   ;  8  went on to the next column: back
        ld l, a                 ;  5  to this column, line 0
        inc h                   ;  5: of the next row of cells
        ret                     ; 11

; vaddr: B = x, C = y -> HL = the address of the byte that holds pixel (x, y),
; in the patterns of a Graphic II screen whose names run 0 to 255 in each
; third; add $2000 for its colours. Uses A.
vaddr:  ld a, c                 ;  5
        rrca                    ;  5
        rrca                    ;  5
        rrca                    ;  5
        and $1F                 ;  8: y / 8, the row of characters
        ld h, a                 ;  5
        ld a, b                 ;  5
        and $F8                 ;  8: the column of characters, x 8
        ld l, a                 ;  5
        ld a, c                 ;  5
        and 7                   ;  8: the line in the cell
        or l                    ;  5
        ld l, a                 ;  5
        ret                     ; 11
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
